import { useState } from 'react';
import NotificationCenter from './NotificationCenter';

export default function App() {
  const [messages, setMessages] = useState<string[]>([]);

  const handleToast = (type: 'success' | 'warning' | 'error') => {
    const message = `This is a ${type} toast message.`;
    setMessages((prev) => [message, ...prev.slice(0, 4)]);
  };

  const clearMessages = () => {
    setMessages([]);
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4">
      <h1 className="text-2xl font-bold mb-6 text-gray-800">Notification Center</h1>
      <div className="flex flex-wrap gap-4 mb-6">
        <button
          onClick={() => handleToast('success')}
          className="px-4 py-2 bg-green-500 text-white rounded-md hover:bg-green-600 transition"
        >
          Success
        </button>
        <button
          onClick={() => handleToast('warning')}
          className="px-4 py-2 bg-yellow-500 text-white rounded-md hover:bg-yellow-600 transition"
        >
          Warning
        </button>
        <button
          onClick={() => handleToast('error')}
          className="px- 4 py-2 bg-red-500 text-white rounded-md hover:bg-red-600 transition"
        >
          Error
        </button>
      </div>
      <NotificationCenter messages={messages} onClear={clearMessages} />
    </div>
  );
}
```

