### NotificationCenter.tsx
```tsx
import React from 'react';

interface Message {
  text: string;
  type: 'success' | 'warning' | 'error';
}

interface NotificationCenterProps {
  messages: string[];
  onClear: () => void;
}

export default function NotificationCenter({ messages, onClear }: NotificationCenterProps) {
  const lastFive = messages.length > 5 ? messages.slice(0, 5) : messages;

  return (
    <div className="w-full max-w-md bg-white rounded-lg shadow-md p-4 border border-gray-200">
      <h2 className="text-lg font-semibold mb-4 text-gray-800">Recent Messages</h2>
      {lastFive.length > 0 ? (
        <ul className="space-y-2 mb-4">
          {lastFive.map((msg, index) => (
            <li
              key={index}
              className="p-2 bg-gray-50 rounded text-sm text-gray-700"
            >
              {msg}
            </li>
          ))}
        </ul>
      ) : (
        <p className="text-gray-500 text-sm">No messages yet.</p>
      )}
      <button
        onClick={onClear}
        className="w-full py-2 text-sm bg-gray-200 hover:bg-gray-300 text-gray-700 rounded transition font-medium"
      >
        Clear All
      </button>
    </div>
  );
}
```

